            function formatTime(seconds) { var h=Math.floor(seconds/3600),m=Math.floor((seconds%3600)/60),s=(seconds%60).toFixed(3); return (h>0?h+":":"")+(m<10?"0":"")+m+":"+(s<10?"0":"")+s; }
            function getVideoName(video) { var so=video.closest('[data-acc-text]'); if(so) return so.getAttribute("data-acc-text"); return null; }
            function getFallbackName(video) { var src=video.currentSrc||video.src||""; var match=src.match(/story_content\/([^?]+)/); if(match) return decodeURIComponent(match[1]).replace(/\.[^.]+$/,""); return "Video"; }

