                if(!videoSessions[id]) videoSessions[id]={sessionId:generateSessionId(),name:null,segments:[],segStart:null,lastSpeed:1,seekFrom:0,stableDuration:null};
                if(!videoSessions[id].name) videoSessions[id].name=getVideoName(video);
