                if(videoContainer){ videoContainer.addEventListener('pointerdown',markUserInteraction,sig); videoContainer.addEventListener('pointerup',markUserInteraction,sig); videoContainer.addEventListener('keydown',markUserInteraction,sig); videoContainer.addEventListener('click',markUserInteraction,sig); }
                video.addEventListener('pointerdown',markUserInteraction,sig); video.addEventListener('click',markUserInteraction,sig); video.addEventListener('keydown',markUserInteraction,sig);

                function isPlayerControl(el) { if (!el || !el.closest) return false; return !!(el.closest('[class*="volume"]')||el.closest('[class*="mute"]')||el.closest('[class*="audio"]')||el.closest('.cs-player-btn')||el.closest('.slide-object-scriptedcontrol')||el.closest('[data-model-id*="volume"]')||el.closest('[data-model-id*="mute"]')||el.closest('.player-controls')||el.closest('.cs-player')); }
                document.addEventListener('pointerdown', function(e) { if (isPlayerControl(e.target)) markUserInteraction(); }, {capture:true, signal:ac.signal});
                document.addEventListener('click', function(e) { if (isPlayerControl(e.target)) markUserInteraction(); }, {capture:true, signal:ac.signal});

                video.addEventListener("play",function(){ if(!isVideoVisible) return; if(!document.body.contains(video)||(video.getBoundingClientRect().width===0)) return; if(Date.now()<seekGraceUntil&&!firstPlaySent) return; if(seekInProgress||justSeeked) return; if(firstPlaySent){session.segStart=video.currentTime;sendVideoStatement("played","played",video,session);return;} lastPlayTime=Date.now(); }, sig);

                video.addEventListener("pause",function(){ if(!isVideoVisible) return; if(!document.body.contains(video)||(video.getBoundingClientRect().width===0)) return; if(video.duration&&(video.duration-video.currentTime)<0.5) return; if(!firstPlaySent){if(Date.now()-lastPlayTime<500)return;} if(session.segStart!==null&&Math.abs(video.currentTime-session.segStart)<0.1){session.segStart=null;return;} var pauseTime=video.currentTime, pauseDuration=video.duration; pendingPauseTimer=setTimeout(function(){ pendingPauseTimer=null; if(!document.body.contains(video)||(video.getBoundingClientRect().width===0))return; if(Date.now()<seekGraceUntil)return; if(session.segStart!==null){session.segments.push(session.segStart.toFixed(3)+"[.]"+pauseTime.toFixed(3));session.segStart=null;} var progress=0; if(pauseDuration&&pauseDuration>0) progress=Math.min(1,pauseTime/pauseDuration); sendVideoStatement("paused","paused",video,session,null,{"https://w3id.org/xapi/video/extensions/progress":Math.round(progress*1000)/1000,"https://w3id.org/xapi/video/extensions/played-segments":session.segments.join("[,]")}); },500); }, sig);

