    var lessonTitleManual = "";
    try { lessonTitleManual = player.GetVar("LessonTitleSetManually") || ""; } catch(e) {}
    var LESSON_TITLE = lessonTitleManual || WorkdayContext.courseTitle || "Untitled Lesson";

