            sendReceived: function(cb) { this.sendStatement("http://adlnet.gov/expapi/verbs/received", "received", LESSON_ACTIVITY_ID, COURSE_TITLE + " | " + LESSON_TITLE, "http://adlnet.gov/expapi/activities/course", null, {completion: true, duration: getSessionDuration()}, cb); },
