            var videoSessions = {};

            function generateSessionId() { return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,function(c){var r=Math.random()*16|0;return(c==='x'?r:(r&0x3|0x8)).toString(16);}); }
            function formatTime(seconds) { var h=Math.floor(seconds/3600),m=Math.floor((seconds%3600)/60),s=(seconds%60).toFixed(3); return (h>0?h+":":"")+(m<10?"0":"")+m+":"+(s<10?"0":"")+s; }
