  // sign-off from David & Sumita; set to false to count all visible time.
  var EXCLUDE_IDLE = true;

  // VERSION
  var VERSION = "ActiveTime Tracker v2.8 (v2.7 + desktop video-focus fix, defect Issue 1)";
  var BUILD = "2026-08-20";
