    try { selectedValue = player.GetVar("Q3_Answer") || ""; } catch(e) {}
    //                                   ▲▲▲ FIELD 1 ▲▲▲
    //                   Your Storyline text variable name for this question

    try { isCorrect = !!player.GetVar("Q3_Correct"); } catch(e) {}
    //                                 ▲▲▲ FIELD 2 ▲▲▲
    //                 Your Storyline True/False variable name for this question

