window.Script309 = function()
{
  // ============================================================
// BOOKMARK FIX: Force cmi.exit = "suspend" on every Terminate
// Ensures bookmarking works even after module is marked complete
// ============================================================
(function() {
    if (window._scormExitFixApplied) return;
    window._scormExitFixApplied = true;

    function findAPI() {
        var api = null;
        try {
            var pw = window.opener.getPlayerWindow();
            if (pw && pw.API_1484_11) api = pw.API_1484_11;
        } catch(e) {}
        if (!api && window.SCORM2004_objAPI) api = window.SCORM2004_objAPI;
        if (!api) {
            var w = window;
            for (var i = 0; i < 10 && !api; i++) {
                if (w.parent && w.parent !== w) {
                    if (w.parent.API_1484_11) {
                        api = w.parent.API_1484_11;
                        break;
                    }
                    w = w.parent;
                } else break;
            }
        }
        if (!api && window.API_1484_11) api = window.API_1484_11;
        return api;
    }

    var api = findAPI();
    if (!api || !api.Terminate) return;

    var originalTerminate = api.Terminate.bind(api);

    api.Terminate = function(param) {
        try {
            api.SetValue("cmi.exit", "suspend");
        } catch(e) {
            console.warn("[BookmarkFix] Could not set cmi.exit:", e);
        }
        return originalTerminate(param);
    };

    console.log("[BookmarkFix] Installed — cmi.exit=suspend forced on every Terminate");
})();


}

window.Script310 = function()
{
  // ============================================================
// Internet Connection Warning
// Displays a text-only modal when the browser goes offline
// ============================================================

(function () {
    // Prevent the script from being installed more than once
    if (window._networkWarningInstalled) return;
    window._networkWarningInstalled = true;

    var WARNING_ID = "storyline-network-warning";

    function createWarning() {
        var existingWarning = document.getElementById(WARNING_ID);

        if (existingWarning) {
            return existingWarning;
        }

        // Full-screen overlay
        var warning = document.createElement("div");

        warning.id = WARNING_ID;

        warning.setAttribute("role", "alertdialog");
        warning.setAttribute("aria-modal", "true");
        warning.setAttribute("aria-live", "assertive");
        warning.setAttribute(
            "aria-label",
            "Internet connection lost"
        );

        warning.style.cssText =
            "position:fixed;" +
            "inset:0;" +
            "display:none;" +
            "align-items:center;" +
            "justify-content:center;" +
            "background:rgba(0,0,0,0.72);" +
            "z-index:2147483647;" +
            "pointer-events:auto;";

        // Text-only message box
        var messageBox = document.createElement("div");

        messageBox.style.cssText =
            "box-sizing:border-box;" +
            "width:calc(100% - 48px);" +
            "max-width:620px;" +
            "margin:24px;" +
            "padding:48px 40px;" +
            "background:#ffffff;" +
            "border-radius:12px;" +
            "box-shadow:0 8px 32px rgba(0,0,0,0.30);" +
            "font-family:Arial,Helvetica,sans-serif;" +
            "text-align:center;" +
            "color:#222222;";

        // Heading
        var heading = document.createElement("div");

        heading.textContent = "Internet connection lost";

        heading.style.cssText =
            "margin:0 0 20px 0;" +
            "font-size:30px;" +
            "font-weight:700;" +
            "line-height:1.25;";

        // Supporting message
        var message = document.createElement("div");

        message.textContent =
            "Your progress may not be saved while you are offline. " +
            "Please reconnect to the internet before continuing.";

        message.style.cssText =
            "margin:0;" +
            "font-size:19px;" +
            "font-weight:400;" +
            "line-height:1.5;";

        messageBox.appendChild(heading);
        messageBox.appendChild(message);
        warning.appendChild(messageBox);

        document.body.appendChild(warning);

        return warning;
    }

    function showOfflineWarning() {
        var warning = createWarning();

        warning.style.display = "flex";

        // Move keyboard focus to the warning
        warning.setAttribute("tabindex", "-1");

        try {
            warning.focus();
        } catch (error) {}
    }

    function hideOfflineWarning() {
        var warning = document.getElementById(WARNING_ID);

        if (warning) {
            warning.style.display = "none";
        }
    }

    // Listen for browser connection changes
    window.addEventListener("offline", showOfflineWarning);
    window.addEventListener("online", hideOfflineWarning);

    // Check the connection when the script first runs
    if (navigator.onLine === false) {
        showOfflineWarning();
    }
})();
}

window.Script311 = function()
{
  // ============================================================
// Module Timeout — FIXED VERSION
// Sets Module_Timeout to true after 5min (300s) inactivity
// (kept in step with the Active Time idle rule so the two never drift)
// FIX: Added guard to prevent multiple setInterval instances
// ============================================================

(function () {

  var store;
  try {
    store = window.opener || window;
    if (!store.__inactivityStore) {
      store.__inactivityStore = { inactiveTime: 0, timedOut: false, intervalId: null };
    }
  } catch (e) {
    store = window;
    if (!store.__inactivityStore) {
      store.__inactivityStore = { inactiveTime: 0, timedOut: false, intervalId: null };
    }
  }

  var state = store.__inactivityStore;

  // *** FIX: Clear any existing interval before starting a new one ***
  if (state.intervalId !== null) {
    clearInterval(state.intervalId);
    state.intervalId = null;
  }

  function isVideoPlaying() {
    var videos = document.querySelectorAll("video");
    for (var i = 0; i < videos.length; i++) {
      if (!videos[i].paused && !videos[i].ended && videos[i].readyState > 2) {
        return true;
      }
    }
    return false;
  }

  function checkInactivity() {
    if (document.hidden) return;
    if (isVideoPlaying()) return;

    state.inactiveTime++;

    if (state.inactiveTime >= 300 && !state.timedOut) {
      state.timedOut = true;
      try {
        var player = GetPlayer();
        player.SetVar("Module_Timeout", true);
      } catch (e) {}
    }
  }

  function resetInactivity() {
    state.inactiveTime = 0;
    if (state.timedOut) {
      state.timedOut = false;
      try {
        var player = GetPlayer();
        player.SetVar("Module_Timeout", false);
      } catch (e) {}
    }
  }

  // *** FIX: Remove stale listeners before re-adding ***
  if (state._resetHandler) {
    document.removeEventListener("mousemove", state._resetHandler);
    document.removeEventListener("mousedown", state._resetHandler);
    document.removeEventListener("click", state._resetHandler);
    document.removeEventListener("keydown", state._resetHandler);
    document.removeEventListener("touchstart", state._resetHandler);
    document.removeEventListener("scroll", state._resetHandler);
  }
  state._resetHandler = resetInactivity;

  document.addEventListener("mousemove", resetInactivity);
  document.addEventListener("mousedown", resetInactivity);
  document.addEventListener("click", resetInactivity);
  document.addEventListener("keydown", resetInactivity);
  document.addEventListener("touchstart", resetInactivity);
  document.addEventListener("scroll", resetInactivity);

  // *** FIX: Store interval ID for cleanup on re-execution ***
  state.intervalId = setInterval(checkInactivity, 1000);

})();


}

