    videoSelector:
      ".slide-object-video video, " +
      ".video-slide-object video, " +
      ".modern-video video",
    seekbarSelector: ".modern-video-controls .video-seekbar",
    /* Includes multiple videos and videos initially hidden on slide layers. */
