    var LAUNCHR_CONFIG = { _domain:"https://fb.learninglocker.net/api/launchr", _auth:"Basic NDkyMDI5YzkyYmY1ZjU1NDQ0ZjdkNDI4MWVlN2NjZDk2OGFlYmY3Zjo3Y2Q4NGQzMjkzN2Y5OTQzZGJhOGQyYmIwMDFmZjEzODEzY2JlZDlj", _accountHomePage: WorkdayContext.lmsBaseUrl||"https://impl.workday.com/facebook8/learning", _xapiVersion:"1.0.1" };
    var COURSE_ACTIVITY_ID = (WorkdayContext.lmsBaseUrl && WorkdayContext.courseId) ? WorkdayContext.lmsBaseUrl+"/course/"+WorkdayContext.courseId : "https://impl.workday.com/facebook8/learning/course/episode-4-xapi";
    var LESSON_ACTIVITY_ID = (WorkdayContext.lmsBaseUrl && WorkdayContext.courseId && WorkdayContext.lessonId) ? WorkdayContext.lmsBaseUrl+"/course/"+WorkdayContext.courseId+"/lesson/"+WorkdayContext.lessonId : COURSE_ACTIVITY_ID;
    log("info","Course Activity ID: "+COURSE_ACTIVITY_ID);
    log("info","Lesson Activity ID: "+LESSON_ACTIVITY_ID);

    // STEP 4: ADL Launch
    log("step", "  STEP 4: ADL Launch to Learning Locker");
    function createLaunchSession(cb) {
        var sid = generateUUID();
        var url = LAUNCHR_CONFIG._domain+"/session/"+sid+"/launch";
        var payload = { statement: { actor: { account: { homePage: LAUNCHR_CONFIG._accountHomePage, name: learnerId||"unknown" }, name: displayName||"Unknown" } }, ttl: 480 };
        var xhr = new XMLHttpRequest();
        xhr.onreadystatechange = function() {
            if (xhr.readyState===4) {
                if (xhr.status===200) { try{JSON.parse(xhr.responseText);log("success","Launch session created");}catch(e){} } else { log("warn","Launch POST HTTP "+xhr.status+" (non-critical)"); }
                cb(null, { endpoint: LAUNCHR_CONFIG._domain.replace("/api/launchr","")+"/data/xAPI/", auth: LAUNCHR_CONFIG._auth, actor: { account:{homePage:LAUNCHR_CONFIG._accountHomePage,name:learnerId}, name:displayName }, registration: sid });
            }
        };
        xhr.onerror = function() { log("warn","Launch POST network error — using direct auth"); cb(null, { endpoint: LAUNCHR_CONFIG._domain.replace("/api/launchr","")+"/data/xAPI/", auth: LAUNCHR_CONFIG._auth, actor: { account:{homePage:LAUNCHR_CONFIG._accountHomePage,name:learnerId}, name:displayName }, registration: sid }); };
        xhr.open("POST", url, true);
        xhr.setRequestHeader("Content-Type","application/json");
        xhr.setRequestHeader("Authorization", LAUNCHR_CONFIG._auth);
        xhr.send(JSON.stringify(payload));
    }

    // STEP 5: Build xAPI Bridge
