                fetch(lrs.endpoint+"statements",{method:"POST",headers:{"Content-Type":"application/json","Authorization":lrs.auth,"X-Experience-API-Version":LAUNCHR_CONFIG._xapiVersion},body:JSON.stringify(stmt)})
