            sendSatisfied: function(cb) { this.sendStatement("http://adlnet.gov/expapi/verbs/satisfied", "satisfied", LESSON_ACTIVITY_ID, COURSE_TITLE + " | " + LESSON_TITLE, "http://adlnet.gov/expapi/activities/course", null, {completion: true, duration: getSessionDuration()}, cb); },
            sendTerminated: function(cb) { this.sendStatement("http://adlnet.gov/expapi/verbs/terminated", "terminated", LESSON_ACTIVITY_ID, COURSE_TITLE + " | " + LESSON_TITLE, "http://adlnet.gov/expapi/activities/course", null, {duration: getSessionDuration()}, function(ok, status, body) { try { Persist.del(INIT_KEY); } catch (e) {} try { Persist.del(LRS_KEY); } catch (e) {} try { Persist.del(LRS_KEY + ":ts"); } catch (e) {} try { Persist.del("xapiLaunch:sessionStart"); } catch (e) {} try { var op = safeOpener(); if (op) { op.__xapiActive = false; } } catch (e) {} if (cb) { cb(ok, status, body); } }); },
            sendViewed: function(term, definition, cb) { this.sendStatement("http://adlnet.gov/expapi/verbs/viewed", "viewed", LESSON_ACTIVITY_ID + "/glossary/" + encodeURIComponent(term), term, "http://adlnet.gov/expapi/activities/resource", {"http://id.tincanapi.com/extension/tags": {term: term, definition: definition}}, null, cb); }
