                var result={extensions:resultExt};
                if(resultExt.completion){result.completion=resultExt.completion;delete resultExt.completion;}
                var slideName=""; try{slideName=GetPlayer().GetVar("JS_VideoName")||"";}catch(e){}
                var fullName=bridge.COURSE_TITLE+" | "+(slideName||"Untitled Video");
                bridge.sendStatement("https://w3id.org/xapi/video/verbs/"+verb,verbDisplay,bridge.LESSON_ACTIVITY_ID+"/video/"+encodeURIComponent(slideName||session.name),fullName,"https://w3id.org/xapi/video/activity-type/video",buildVideoContext(session,video,extraCtx),result);
