      try { var op = safeOpener(); if (op && op.__activeTimeStore) { delete op.__activeTimeStore[key]; } } catch (e) {}
      try { sessionStorage.removeItem(key); } catch (e) {}
      try { localStorage.removeItem(key); } catch (e) {}
