  try { completedLastSession = !!Persist.get(COMPLETED_KEY); } catch (e) {}
  var isNewAttempt =
    cmiEntry === "ab-initio" || cmiCompletionStatus === "completed" || completedLastSession;
  log(
    "cmi.entry=" +
      cmiEntry +
      " | completion=" +
      cmiCompletionStatus +
      " | completedLast=" +
      completedLastSession +
      " | " +
      (isNewAttempt ? "NEW" : "RESUME"),
  );

  // STEP 3: Restore accumulated time
  // Restored from the durable store only (scoped per-episode). The old SCORM
  // suspend_data path was dead weight: GetDataChunkValue is not defined in the
  // published package (it threw every time), and Storyline overwrites the
