    if (!scormAPI && window.SCORM2004_objAPI) scormAPI = window.SCORM2004_objAPI;
    if (!scormAPI) { var w = window; for (var i=0; i<10 && !scormAPI; i++) { if (w.parent && w.parent !== w) { if (w.parent.API_1484_11) { scormAPI = w.parent.API_1484_11; break; } w = w.parent; } else break; } }
    if (!scormAPI && window.API_1484_11) scormAPI = window.API_1484_11;
    if (scormAPI) { try { learnerId = scormAPI.GetValue("cmi.learner_id")||""; learnerName = scormAPI.GetValue("cmi.learner_name")||""; log("success","Learner: "+learnerId+" / "+learnerName); } catch(e){} }
    else { learnerId = WorkdayContext.learnerId; learnerName = WorkdayContext.learnerName; }
    var displayName = learnerName;
    if (learnerName && learnerName.indexOf(",")>-1) { var np=learnerName.split(","); displayName=np[1].trim()+" "+np[0].trim(); }

    // STEP 3: Configuration
    var LAUNCHR_CONFIG = { _domain:"https://fb.learninglocker.net/api/launchr", _auth:"Basic NDkyMDI5YzkyYmY1ZjU1NDQ0ZjdkNDI4MWVlN2NjZDk2OGFlYmY3Zjo3Y2Q4NGQzMjkzN2Y5OTQzZGJhOGQyYmIwMDFmZjEzODEzY2JlZDlj", _accountHomePage: WorkdayContext.lmsBaseUrl||"https://impl.workday.com/facebook8/learning", _xapiVersion:"1.0.1" };
    var COURSE_ACTIVITY_ID = (WorkdayContext.lmsBaseUrl && WorkdayContext.courseId) ? WorkdayContext.lmsBaseUrl+"/course/"+WorkdayContext.courseId : "https://impl.workday.com/facebook8/learning/course/episode-4-xapi";
    var LESSON_ACTIVITY_ID = (WorkdayContext.lmsBaseUrl && WorkdayContext.courseId && WorkdayContext.lessonId) ? WorkdayContext.lmsBaseUrl+"/course/"+WorkdayContext.courseId+"/lesson/"+WorkdayContext.lessonId : COURSE_ACTIVITY_ID;
    log("info","Course Activity ID: "+COURSE_ACTIVITY_ID);
    log("info","Lesson Activity ID: "+LESSON_ACTIVITY_ID);

    // STEP 4: ADL Launch
