                var src=video.currentSrc||video.src||"";
                if(!src||src.startsWith("data:")||src.startsWith("blob:")){video.addEventListener("loadedmetadata",function(){trackVideo(video);},{once:true});return;}

                // v5.9.2 FIX: Don't abandon videos with placeholder duration — retry
                // v5.9.3 FIX: Gate so only ONE path can trigger re-init
                if(video.duration&&video.duration<1) {
                    var _retried = false;
                    function retryOnce() { if (_retried) return; _retried = true; trackVideo(video); }
                    video.addEventListener("durationchange", function onDurRetry() {
                        if (video.duration && isFinite(video.duration) && video.duration > 1) {
                            video.removeEventListener("durationchange", onDurRetry);
                            retryOnce();
                        }
                    });
                    video.addEventListener("loadedmetadata", function() { retryOnce(); }, {once:true});
                    return;
                }

                video.dataset.xapiTracked="true";
                var session=getSession(video);

                // v5.9.4 FIX: AbortController to mass-remove all listeners on recycle
                var ac = new AbortController();
                var sig = {signal: ac.signal};

                // v5.9.2/5.9.3 FIX: Detect element recycling
                // v5.9.4 FIX: abort() removes ALL old per-video listeners cleanly
                var _initSrc = video.currentSrc || video.src || "";
                video.addEventListener("loadstart", function onRecycle() {
                    var newSrc = video.currentSrc || video.src || "";
                    if (!newSrc || newSrc.startsWith("data:") || newSrc.startsWith("blob:")) return;
                    if (newSrc === _initSrc) return; // v5.9.3: same src = not a recycle
                    // v5.9.4: Remove ALL old listeners via AbortController
                    ac.abort();
                    // Tear down stale state
                    video.dataset.xapiTracked = "";
                    var oldId = video.dataset.xapiVideoId;
                    if (oldId && videoSessions[oldId]) delete videoSessions[oldId];
                    video.dataset.xapiVideoId = "";
                    video.removeEventListener("loadstart", onRecycle);
                    trackVideo(video); // fresh closures, fresh session, fresh AbortController
                });

                // Stable duration capture (v5.9); v5.9.1: require > 1s
                var stableDuration = null;
                video.addEventListener("durationchange", function() {
                    if (video.duration && isFinite(video.duration) && video.duration > 1) { stableDuration = Math.round(video.duration * 1000) / 1000; session.stableDuration = stableDuration; }
                }, sig);
                if (video.duration && isFinite(video.duration) && video.duration > 1) { stableDuration = Math.round(video.duration * 1000) / 1000; session.stableDuration = stableDuration; }

                video.addEventListener("loadeddata", function() { session.lastSpeed = 1; }, sig);

                var firstPlaySent=false, lastPlayTime=0, pendingPauseTimer=null;
                var justSeeked=false, justSeekedTimer=null, seekInProgress=false;
                var seekGraceUntil=Date.now()+3000;
                var isVideoVisible=true;
                var visObs=new IntersectionObserver(function(entries){entries.forEach(function(entry){isVideoVisible=entry.isIntersecting;});seekGraceUntil=Date.now()+3000;});
                visObs.observe(video);

                var userInteractedRecently=false, userInteractTimer=null;
                function markUserInteraction() { userInteractedRecently=true; clearTimeout(userInteractTimer); userInteractTimer=setTimeout(function(){userInteractedRecently=false;},1500); }

                var videoContainer=video.closest('.slide-object')||video.closest('[data-acc-text]')||video.parentElement;
                if(videoContainer){ videoContainer.addEventListener('pointerdown',markUserInteraction,sig); videoContainer.addEventListener('pointerup',markUserInteraction,sig); videoContainer.addEventListener('keydown',markUserInteraction,sig); videoContainer.addEventListener('click',markUserInteraction,sig); }
                video.addEventListener('pointerdown',markUserInteraction,sig); video.addEventListener('click',markUserInteraction,sig); video.addEventListener('keydown',markUserInteraction,sig);

                function isPlayerControl(el) { if (!el || !el.closest) return false; return !!(el.closest('[class*="volume"]')||el.closest('[class*="mute"]')||el.closest('[class*="audio"]')||el.closest('.cs-player-btn')||el.closest('.slide-object-scriptedcontrol')||el.closest('[data-model-id*="volume"]')||el.closest('[data-model-id*="mute"]')||el.closest('.player-controls')||el.closest('.cs-player')); }
                document.addEventListener('pointerdown', function(e) { if (isPlayerControl(e.target)) markUserInteraction(); }, {capture:true, signal:ac.signal});
                document.addEventListener('click', function(e) { if (isPlayerControl(e.target)) markUserInteraction(); }, {capture:true, signal:ac.signal});

                video.addEventListener("play",function(){ if(!isVideoVisible) return; if(!document.body.contains(video)||(video.getBoundingClientRect().width===0)) return; if(Date.now()<seekGraceUntil&&!firstPlaySent) return; if(seekInProgress||justSeeked) return; if(firstPlaySent){session.segStart=video.currentTime;sendVideoStatement("played","played",video,session);return;} lastPlayTime=Date.now(); }, sig);

                video.addEventListener("pause",function(){ if(!isVideoVisible) return; if(!document.body.contains(video)||(video.getBoundingClientRect().width===0)) return; if(video.duration&&(video.duration-video.currentTime)<0.5) return; if(!firstPlaySent){if(Date.now()-lastPlayTime<500)return;} if(session.segStart!==null&&Math.abs(video.currentTime-session.segStart)<0.1){session.segStart=null;return;} var pauseTime=video.currentTime, pauseDuration=video.duration; pendingPauseTimer=setTimeout(function(){ pendingPauseTimer=null; if(!document.body.contains(video)||(video.getBoundingClientRect().width===0))return; if(Date.now()<seekGraceUntil)return; if(session.segStart!==null){session.segments.push(session.segStart.toFixed(3)+"[.]"+pauseTime.toFixed(3));session.segStart=null;} var progress=0; if(pauseDuration&&pauseDuration>0) progress=Math.min(1,pauseTime/pauseDuration); sendVideoStatement("paused","paused",video,session,null,{"https://w3id.org/xapi/video/extensions/progress":Math.round(progress*1000)/1000,"https://w3id.org/xapi/video/extensions/played-segments":session.segments.join("[,]")}); },500); }, sig);

                video.addEventListener("timeupdate",function onReady(){ if(!firstPlaySent&&video.currentTime>0.5){ if(!document.body.contains(video)||video.closest('[style*="display: none"]'))return; firstPlaySent=true; session.segStart=0; sendVideoStatement("played","played",video,session); video.removeEventListener("timeupdate",onReady); } }, sig);

                var lastKnownTime=0, previousKnownTime=0;
                video.addEventListener("timeupdate",function(){previousKnownTime=lastKnownTime;lastKnownTime=video.currentTime;}, sig);

                video.addEventListener("seeking",function(){seekInProgress=true;if(pendingPauseTimer){clearTimeout(pendingPauseTimer);pendingPauseTimer=null;}session.seekFrom=previousKnownTime;}, sig);

                video.addEventListener("seeked",function(){ seekInProgress=false; justSeeked=true; clearTimeout(justSeekedTimer); justSeekedTimer=setTimeout(function(){justSeeked=false;},150); if(!firstPlaySent||Date.now()<seekGraceUntil)return; var distance=Math.abs(video.currentTime-session.seekFrom); if(distance<1)return; sendVideoStatement("seeked","seeked",video,session,null,{"https://w3id.org/xapi/video/extensions/time-from":Math.round(session.seekFrom*1000)/1000,"https://w3id.org/xapi/video/extensions/time-to":Math.round(video.currentTime*1000)/1000}); }, sig);

                // INTERACTED (speed change) — v5.8 FIX: re-enable captions on mobile
                video.addEventListener("ratechange",function(){
                    if(video.playbackRate!==session.lastSpeed){ session.lastSpeed=video.playbackRate; sendVideoStatement("interacted","interacted",video,session,{"https://w3id.org/xapi/video/extensions/speed":video.playbackRate+"x"}); }
                    if (/Mobi|Android|iPhone|iPad/i.test(navigator.userAgent)) {
                        setTimeout(function() {
                            for (var i = 0; i < video.textTracks.length; i++) { if (video.textTracks[i].mode === "disabled" || video.textTracks[i].mode === "hidden") { video.textTracks[i].mode = "showing"; } }
                            try { var ccPanel = document.querySelector('.caption-panel, .cc-container, [class*="closed-caption"], [class*="subtitle"]'); if (ccPanel) { ccPanel.style.display = "none"; void ccPanel.offsetHeight; ccPanel.style.display = ""; } } catch (e) {}
                        }, 250);
                    }
                }, sig);

                // COMPLETED (video ended) — v5.9: endedSent guard + stableDuration
                var endedSent = false;
                video.addEventListener("ended",function(){
                    if (endedSent) return;
                    endedSent = true;
                    if(session.segStart!==null){session.segments.push(session.segStart.toFixed(3)+"[.]"+video.currentTime.toFixed(3));session.segStart=null;}
                    sendVideoStatement("completed","completed",video,session,{"https://w3id.org/xapi/video/extensions/length":stableDuration||(video.duration>1?Math.round(video.duration*1000)/1000:undefined)},{completion:true,"https://w3id.org/xapi/video/extensions/progress":1,"https://w3id.org/xapi/video/extensions/played-segments":session.segments.join("[,]")});
                }, sig);

                var volumeTimer=null, lastMuted=video.muted, MAX_VOLUME=0.75;
                function normalizedVolume(){var v=Math.min(1,Math.round((video.volume/MAX_VOLUME)*100)/100);return v===0?"muted":String(v);}
                var muteDebounceUntil=0;
                video.addEventListener("volumechange",function(){ if(!firstPlaySent)return; if(Date.now()<seekGraceUntil)return; if(!userInteractedRecently)return; if(video.muted!==lastMuted){ lastMuted=video.muted; muteDebounceUntil=Date.now()+3000; sendVideoStatement("interacted","interacted",video,session,{"https://w3id.org/xapi/video/extensions/volume":video.muted?"muted":normalizedVolume()}); return; } if(Date.now()<muteDebounceUntil)return; clearTimeout(volumeTimer); volumeTimer=setTimeout(function(){sendVideoStatement("interacted","interacted",video,session,{"https://w3id.org/xapi/video/extensions/volume":normalizedVolume()});},500); }, sig);

                if (!window._xapiFullscreenAttached) { window._xapiFullscreenAttached = true; var _lastFullscreenVideo = null;
                    document.addEventListener("fullscreenchange", function() { var fsVideo; if (document.fullscreenElement) { fsVideo = document.fullscreenElement.querySelector("video") || document.querySelector("video"); _lastFullscreenVideo = fsVideo; } else { fsVideo = _lastFullscreenVideo || document.querySelector("video"); } if (fsVideo && fsVideo.dataset.xapiVideoId) { var fsSession = videoSessions[fsVideo.dataset.xapiVideoId]; if (fsSession) { sendVideoStatement("interacted", "interacted", fsVideo, fsSession, {"https://w3id.org/xapi/video/extensions/full-screen": !!document.fullscreenElement}); } } });
                }

                video.addEventListener("enterpictureinpicture",function(){sendVideoStatement("interacted","interacted",video,session,{"https://w3id.org/xapi/video/extensions/picture-in-picture":true});}, sig);
                video.addEventListener("leavepictureinpicture",function(){sendVideoStatement("interacted","interacted",video,session,{"https://w3id.org/xapi/video/extensions/picture-in-picture":false});}, sig);

