            var lessonIdx = pathParts.indexOf("lesson");
            if (courseIdx > -1 && pathParts[courseIdx + 1]) WorkdayContext.courseId = pathParts[courseIdx + 1];
            if (lessonIdx > -1 && pathParts[lessonIdx + 1]) WorkdayContext.lessonId = pathParts[lessonIdx + 1];
            var learningIdx = pathParts.indexOf("learning");
            if (learningIdx > 1) WorkdayContext.tenant = pathParts[learningIdx - 1];
