  console.log(
    "%c" + VERSION + "  build " + BUILD,
    "background:#004d40;color:#b2dfdb;padding:3px 8px;border-radius:3px;font-weight:bold;"
  );
  console.log(
    "%c[ActiveTime] load #" + loadCount + " | " + (isNewAttempt ? "NEW" : "RESUME") +
      " | restored " + Math.floor(restoredBaselineMs / 1000) + "s | SCORM API " + (apiRef ? "found" : "MISSING"),
    "background:#e0f7fa;color:#006064;padding:2px 6px;border-radius:3px;"
  );

