      "position:fixed;bottom:8px;right:8px;z-index:2147483647;" +
      "font:12px/1.45 monospace;background:rgba(0,42,42,0.88);color:#7fffd4;" +
      "padding:8px 10px;border-radius:6px;pointer-events:none;white-space:pre;" +
      "box-shadow:0 2px 8px rgba(0,0,0,0.4);min-width:190px;";
