        player.SetVar("JS_Environment", WorkdayContext.environment);
        player.SetVar("JS_LmsUrl", WorkdayContext.lmsBaseUrl);
        player.SetVar("JS_RegistrationId", WorkdayContext.registrationId);
        player.SetVar("JS_LearnerId", WorkdayContext.learnerId);
        player.SetVar("JS_LearnerName", WorkdayContext.learnerName);
