            sendInteracted: function(description, extraExt, cb) { this.sendStatement("http://adlnet.gov/expapi/verbs/interacted", "interacted", LESSON_ACTIVITY_ID, COURSE_TITLE + " | " + (description || this._lastPagePath || LESSON_TITLE), "http://adlnet.gov/expapi/activities/course", extraExt, null, cb); },
