window.Script441 = function()
{
  (function () {
    var bridge = window._xapiBridge;

    if (!bridge || !bridge.LESSON_ACTIVITY_ID) {
        console.warn(
            "[xAPI-Bridge] Captions statement not sent — bridge unavailable"
        );
        return;
    }

    var player = GetPlayer();
    var currentValue = false;
    var slideName = "";

    try {
        currentValue = player.GetVar("CC_Enabled");

        slideName =
            player.GetVar("JS_VideoName") ||
            "Captions";
    } catch (error) {
        console.warn(
            "[xAPI-Bridge] Could not read caption variables:",
            error
        );
        return;
    }

    var normalisedValue = String(currentValue)
        .trim()
        .toLowerCase();

    var currentlyEnabled =
        currentValue === true ||
        currentValue === 1 ||
        normalisedValue === "true" ||
        normalisedValue === "1";

    // Toggle the custom caption variable.
    var isEnabled = !currentlyEnabled;

    try {
        player.SetVar("CC_Enabled", isEnabled);
    } catch (error) {
        console.warn(
            "[xAPI-Bridge] Could not update CC_Enabled:",
            error
        );
        return;
    }

    var captionStatus = isEnabled
        ? "enabled"
        : "disabled";

    bridge.sendStatement(
        "https://w3id.org/xapi/video/verbs/interacted",
        "interacted",

        bridge.LESSON_ACTIVITY_ID +
            "/video/" +
            encodeURIComponent(slideName),

        bridge.COURSE_TITLE +
            " | " +
            slideName,

        "https://w3id.org/xapi/video/activity-type/video",

        {
            "https://w3id.org/xapi/video/extensions/cc-subtitle-enabled":
                isEnabled,

            "https://w3id.org/xapi/video/extensions/cc-subtitle-lang":
                "en",

            "http://id.tincanapi.com/extension/condition-type":
                "closed-captions",

            "http://id.tincanapi.com/extension/condition-value":
                captionStatus
        },

        null
    );

    console.log(
        "[xAPI-Bridge] Closed captions " +
        captionStatus +
        " | CC_Enabled changed from",
        currentValue,
        "to",
        isEnabled
    );
})();
}

