      try { var op = safeOpener(); if (op && op.__activeTimeStore && op.__activeTimeStore[key] != null) { s = op.__activeTimeStore[key]; } } catch (e) {}
      if (s == null) { try { s = sessionStorage.getItem(key); } catch (e) {} }
      if (s == null) { try { s = localStorage.getItem(key); } catch (e) {} }
