  var _isMobile = false;
  try { _isMobile = /iP(hone|ad|od)|Android|Mobile/i.test(navigator.userAgent || ""); } catch (e) {}
  if (!_isMobile) {
    // DESKTOP: unchanged from v2.4.
    try { if (apiRef) { _scopeParts.push(apiRef.GetValue("cmi.learner_id") || ""); } } catch (e) {}
  } else {
    // MOBILE: live learner_id if connected, else the cached one.
    var _lid = "";
    try { if (apiRef) { _lid = apiRef.GetValue("cmi.learner_id") || ""; } } catch (e) {}
    var _lidKey = "activeTime:" + _hash(location.pathname || "") + ":lid";
    if (_lid) { try { localStorage.setItem(_lidKey, _lid); } catch (e) {} }
    else { try { _lid = localStorage.getItem(_lidKey) || ""; } catch (e) {} }
    _scopeParts.push(_lid);
  }
  var SCOPE = _hash(_scopeParts.join("|")) || "default";
  var DURABLE_KEY = "activeTime:" + SCOPE + ":ms";
  var LOADS_KEY = "activeTime:" + SCOPE + ":loads";
  var ATTEMPT_START_KEY = "activeTime:" + SCOPE + ":attemptStart";
  var COMPLETED_KEY = "activeTime:" + SCOPE + ":completed";

  // STEP 2: Determine new attempt vs resume
