            sendExperienced: function(pagePath, cb) { this._lastPagePath = pagePath; this.sendStatement("http://adlnet.gov/expapi/verbs/experienced", "experienced", LESSON_ACTIVITY_ID, COURSE_TITLE + " | " + pagePath, "http://adlnet.gov/expapi/activities/module", null, {duration: getSessionDuration()}, cb); },
            sendFailed: function(score, assessmentType, cb) { this.sendStatement("http://adlnet.gov/expapi/verbs/failed", "failed", LESSON_ACTIVITY_ID, COURSE_TITLE + " | " + LESSON_TITLE, "http://adlnet.gov/expapi/activities/assessment", {"http://id.tincanapi.com/extension/assessment-type": assessmentType || "distributed"}, {score: {raw: score, min: 0, max: 100, scaled: score / 100}, success: false}, cb); },
