            function formatTime(seconds) { var h=Math.floor(seconds/3600),m=Math.floor((seconds%3600)/60),s=(seconds%60).toFixed(3); return (h>0?h+":":"")+(m<10?"0":"")+m+":"+(s<10?"0":"")+s; }
