                if(!isOpen&&lastTranscriptOpen){lastTranscriptOpen=false;var video=document.querySelector("video");if(video){var session=getSession(video);sendVideoStatement("interacted","interacted",video,session,{"http://id.tincanapi.com/extension/condition-type":"transcript","http://id.tincanapi.com/extension/condition-value":"closed"});}}
