            try { Persist.del(LRS_KEY); } catch(e) {}
            try { Persist.del(LRS_KEY + ":ts"); } catch(e) {}
            try { Persist.del("xapiLaunch:sessionStart"); } catch(e) {}
            try { var op = safeOpener(); if (op) { op.__xapiActive = false; } } catch(e) {}

