            var lrs = bridge.lrsConfig;
            var duration = window.getActiveTimeISO8601 ? window.getActiveTimeISO8601() : "PT0S";
            var stmt = { actor: lrs.actor, verb: { id: "http://adlnet.gov/expapi/verbs/terminated", display: {"en": "terminated"} }, object: { objectType: "Activity", id: bridge.LESSON_ACTIVITY_ID, definition: { type: "http://adlnet.gov/expapi/activities/course", name: {"en": bridge.COURSE_TITLE + " | " + bridge.LESSON_TITLE + " | Close"} } }, context: bridge._buildContext(null), result: { duration: duration }, timestamp: new Date().toISOString() };
