                    { objectType:"Activity", id:COURSE_ACTIVITY_ID, definition:{type:"http://adlnet.gov/expapi/activities/course",name:{"en":COURSE_TITLE},extensions:{"https://adaptlearning.org/xapi/extension/model":"course"}} },
                    { objectType:"Activity", id:LESSON_ACTIVITY_ID, definition:{type:"http://adlnet.gov/expapi/activities/module",name:{"en":LESSON_TITLE},extensions:{"https://adaptlearning.org/xapi/extension/model":"page"}} }
